
"use client";
import React, { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { useSession, signOut } from "next-auth/react";

const Navbar = () => {
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const { data: session, status } = useSession();
  const [showdropdown, setShowdropdown] = useState(false);

  // 1. Loading state placeholder
  if (status === "loading") {
    return <nav className="flex justify-between items-center px-4 md:px-15 lg:px-20 py-4 bg-sky-950 shadow-lg min-h-[82px]"></nav>;
  }

  return (
    <nav className="flex justify-between items-center px-4 md:px-15 lg:px-20 py-4 bg-sky-950 shadow-lg">
      
      {/* Logo Section */}
      <div className="flex items-center gap-2 text-2xl font-bold">
        <Link href="/" className="flex items-center text-white hover:text-blue-300 transition duration-300">
          <Image
            src="/logo.png"
            alt="Doc.AI Logo"
            width={50}
            height={50}
            className="rounded-full mr-2"
          />
          MEDI<span className="text-blue-400">FLO</span>
        </Link>
      </div>

      {/* Navigation Links */}
      <div>
        <ul className="flex space-x-10 items-center">
          <li>
            <Link href="/" className="text-blue-50 hover:text-sky-400 font-medium transition duration-300 hidden md:block">Home</Link>
          </li>
          <li>
            <Link href="/about" className="text-gray-50 hover:text-sky-400 font-medium transition duration-300 hidden md:block">About Us</Link>
          </li>
          {session && (
            <li>
              <Link href="/service" className="text-gray-50 hover:text-sky-400 font-medium transition duration-300">
                Services
              </Link>
            </li>
          )}
        </ul>
      </div>

      {/* Auth & Profile Section */}
      <div className="flex items-center gap-4 relative">
        {session ? (
          <>
            {/* User Dropdown */}
            <div className="relative">
              <button 
                onClick={() => setShowdropdown(!showdropdown)} 
                onBlur={() => setTimeout(() => setShowdropdown(false), 200)}
                className="inline-flex items-center justify-center text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:ring-blue-300 font-medium rounded-lg text-sm px-4 py-2.5 focus:outline-none transition" 
                type="button"
              >
                Welcome, <span className="capitalize ml-1">{session.user?.name || "User"}</span>
                <svg className="w-4 h-4 ms-2" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="m19 9-7 7-7-7" />
                </svg>
              </button>

              {/* Dropdown Menu */}
              <div className={`z-50 ${showdropdown ? "absolute" : "hidden"} right-0 mt-2 bg-white divide-y divide-gray-100 rounded-lg shadow-xl w-44`}>
                <ul className="py-2 text-sm text-gray-700">
                  <li>
                    <Link href="/profile" className="block px-4 py-2 hover:bg-gray-100">Profile</Link>
                  </li>
                  <li>
                    <Link href="/service" className="block px-4 py-2 hover:bg-gray-100 md:hidden">Services</Link>
                  </li>
                  <li>
                    <Link href="#" className="block px-4 py-2 hover:bg-gray-100">Your Pages</Link>
                  </li>
                </ul>
              </div>
            </div>

            {/* Logout Confirmation Logic */}
            <div className="flex items-center">
              {isLoggingOut ? (
                <div className="flex gap-2 animate-in fade-in zoom-in duration-200">
                  <button 
                    onClick={() => signOut()}
                    className="bg-red-600 text-white px-3 py-2 rounded-lg font-bold text-xs hover:bg-red-700 shadow-lg"
                  >
                    Confirm Logout?
                  </button>
                  <button 
                    onClick={() => setIsLoggingOut(false)}
                    className="bg-gray-500 text-white px-3 py-2 rounded-lg font-bold text-xs hover:bg-gray-600"
                  >
                    Cancel
                  </button>
                </div>
              ) : (
                <button 
                  onClick={() => setIsLoggingOut(true)}
                  className="bg-emerald-500 hover:bg-emerald-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md transition transform hover:scale-105"
                >
                  Log Out
                </button>
              )}
            </div>
          </>
        ) : (
          /* Logged Out View: Show Login & Sign Up */
          <div className="flex gap-3">
            <Link href="/login">
              <button className="bg-emerald-500 hover:bg-emerald-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md transition transform hover:scale-105">
                Login
              </button>
            </Link>
            <Link href="/register">
              <button className="bg-blue-600 hover:bg-blue-500 text-white font-semibold py-2 px-5 rounded-lg shadow-md transition transform hover:scale-105 active:scale-95">
                Sign Up
              </button>
            </Link>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;